sp_widget.css:
/* ===================================
   KPI CONTAINER
=================================== */

.automed-kpi-container{

    display:flex;
    gap:20px;
    flex-wrap:wrap;

    margin-top:20px;
}

/* ===================================
   KPI CARD
=================================== */

.kpi-card{

    flex:1;
    min-width:220px;

    padding:28px;

    border-radius:22px;

    text-align:center;

    color:white;

    position:relative;

    overflow:hidden;

    cursor:pointer;

    transition:.4s;

    box-shadow:
        0 10px 25px rgba(0,0,0,.15);

    animation:cardEntry .8s ease forwards;

    opacity:0;
}

/* ===================================
   ENTRY ANIMATION
=================================== */

.kpi-card:nth-child(1){
    animation-delay:.1s;
}

.kpi-card:nth-child(2){
    animation-delay:.2s;
}

.kpi-card:nth-child(3){
    animation-delay:.3s;
}

.kpi-card:nth-child(4){
    animation-delay:.4s;
}

@keyframes cardEntry{

    from{
        opacity:0;
        transform:translateY(30px);
    }

    to{
        opacity:1;
        transform:translateY(0);
    }
}

/* ===================================
   HOVER
=================================== */

.kpi-card:hover{

    transform:
        translateY(-8px)
        scale(1.03);

    box-shadow:
        0 20px 40px rgba(0,0,0,.20);
}

/* ===================================
   SHIMMER EFFECT
=================================== */

.kpi-card::before{

    content:"";

    position:absolute;

    top:0;
    left:-100%;

    width:100%;
    height:100%;

    background:linear-gradient(
        90deg,
        transparent,
        rgba(255,255,255,.25),
        transparent
    );

    transition:.8s;
}

.kpi-card:hover::before{

    left:100%;
}

/* ===================================
   FLOATING CIRCLE
=================================== */

.kpi-card::after{

    content:"";

    position:absolute;

    width:120px;
    height:120px;

    border-radius:50%;

    background:rgba(255,255,255,.12);

    top:-40px;
    right:-40px;
}

/* ===================================
   ICON
=================================== */

.kpi-icon{

    font-size:42px;

    margin-bottom:15px;

    animation:iconFloat 4s ease-in-out infinite;
}

@keyframes iconFloat{

    0%{
        transform:translateY(0);
    }

    50%{
        transform:translateY(-8px);
    }

    100%{
        transform:translateY(0);
    }
}

/* ===================================
   VALUE
=================================== */

.kpi-value{

    font-size:42px;

    font-weight:700;

    margin-bottom:10px;

    animation:numberPulse 3s infinite;
}

@keyframes numberPulse{

    0%{
        transform:scale(1);
    }

    50%{
        transform:scale(1.05);
    }

    100%{
        transform:scale(1);
    }
}

/* ===================================
   LABEL
=================================== */

.kpi-label{

    font-size:16px;

    font-weight:600;

    color:rgba(255,255,255,.95);
}

/* ===================================
   GIVEN CARD
=================================== */

.given{

    background:linear-gradient(
        135deg,
        #1B5E20,
        #66BB6A
    );
}

/* ===================================
   DUE CARD
=================================== */

.due{

    background:linear-gradient(
        135deg,
        #E65100,
        #FFB74D
    );

    animation:
        cardEntry .8s ease forwards,
        dueGlow 2s infinite;
}

@keyframes dueGlow{

    0%{
        box-shadow:
            0 0 0 rgba(255,183,77,.4);
    }

    50%{
        box-shadow:
            0 0 25px rgba(255,183,77,.5);
    }

    100%{
        box-shadow:
            0 0 0 rgba(255,183,77,.4);
    }
}

/* ===================================
   MISSED CARD
=================================== */

.missed{

    background:linear-gradient(
        135deg,
        #B71C1C,
        #EF5350
    );
}

/* ===================================
   UPCOMING CARD
=================================== */

.upcoming{

    background:linear-gradient(
        135deg,
        #0D47A1,
        #64B5F6
    );
}

/* ===================================
   MOBILE
=================================== */

@media(max-width:768px){

    .kpi-card{

        min-width:100%;
    }

    .kpi-value{

        font-size:34px;
    }
}
